import { test } from "node:test";
import assert from "node:assert/strict";

import { barSeries, total, cumulativeSeries, monthTicks, labelStep, referenceIndex, stack } from "../static/stats-data.js";

const data = {
  labels: ["Jan", "Feb"],
  km: [10.5, 0],
  hours: [0.5, 0],
  ascent: [120, 0],
  years: [
    { year: 2026, km: [1, 2, null] },
    { year: 2025, km: [0, 5, 7] },
  ],
  goal: 365,
  daysInYear: 365,
};

test("barSeries selects the metric", () => {
  assert.deepEqual(barSeries(data, "ascent"), { x: [0, 1], y: [120, 0] });
  assert.deepEqual(barSeries(data, "unknown").y, [10.5, 0]);
  assert.equal(total(data, "km"), 10.5);
});

test("cumulativeSeries pads years to 366 days and adds a linear goal", () => {
  const { x, series } = cumulativeSeries(data);
  assert.equal(x.length, 366);
  assert.deepEqual(series.map((s) => s.label), ["2026", "2025", "Ziel 365 km"]);
  assert.deepEqual(series[0].values.slice(0, 4), [1, 2, null, null]);
  assert.equal(series[2].values[0], 1);
  assert.equal(series[2].values[364], 365);
  assert.equal(series[2].values[365], null);
  assert.equal(cumulativeSeries({ ...data, goal: 0 }).series.length, 2);
});

test("referenceIndex is the last day with data of the selected year", () => {
  const { series } = cumulativeSeries(data);
  assert.equal(referenceIndex(series), 1);
  assert.equal(referenceIndex([{ values: [null, null] }]), -1);
  assert.equal(referenceIndex([]), -1);
});

test("monthTicks", () => {
  const t = monthTicks();
  assert.equal(t.values.length, 12);
  assert.equal(t.labels[9], "Okt");
});

test("labelStep thins labels on narrow charts", () => {
  assert.equal(labelStep(12, 1000), 1);
  assert.equal(labelStep(53, 1000), 3);
  assert.equal(labelStep(53, 300), 8);
  assert.equal(labelStep(0, 300), 1);
});

test("stack accumulates series for stacked bars", () => {
  const { bands } = stack([[1, 2], [3, null], [0, 4]]);
  assert.deepEqual(bands, [[1, 2], [4, 2], [4, 6]]);
  assert.deepEqual(stack([]).bands, []);
});
